"use strict";(self.webpackChunkPromoScreen=self.webpackChunkPromoScreen||[]).push([[472],{2472:e=>{e.exports=JSON.parse('{"reviews":{"get_pregnant":[{"id":"gp_1","text":"Super App, konnte so meinen Zyklus genau nachvollziehen. Ich wurde mithilfe der App, die mir meinen Eisprung vorhergesagt hat, schwanger! Sie ist immer und überall mit dabei. Sehr übersichtlich und einfach zu bedienen.","userName":"Lisa Vogel"},{"id":"gp_2","text":"Ich verwende die App seit mehreren Jahren. Sie ist übersichtlich und immer korrekt. Dank der Vorhersage meines Eisprungs war es beide Male leicht, schwanger zu werden. Top!","userName":"Claudia B"},{"id":"gp_3","text":"Tolle App. Habe sie installiert, als ich schwanger werden wollte. Man kann in den Schwangerschaftsmodus wechseln und immer sehen, wie das Baby aktuell aussehen würde.","userName":"Anika F"}],"track_cycle":[{"id":"tc_1","text":"Ich find das Update toll. Die individuelle Darstellung des Zyklus und der damit einhergehenden hormonellen Veränderungen ist einfach klasse und erklärt häufig meine Gemütslage :)","userName":"Tülin H"},{"id":"tc_2","text":"Tolle und zuverlässige App mit interessanten Beiträgen rund um den weiblichen Zyklus.","userName":"Jasmin E."},{"id":"tc_3","text":"Super genaue Prognosen. Nie mehr überlegen, wann man Tampons und Co einpacken muss :-)","userName":"Katharina Morrison"}],"follow_pregnancy":[{"id":"fp_1","text":"Super praktisch! Ich nutze Flo schon seit Jahren, auch während meiner Schwangerschaft. Die App hat mich jederzeit mit Statistiken und Infos versorgt 👍","userName":"Sandra Z"},{"id":"fp_2","text":"Toll während der Schwangerschaft und der Zeit danach.","userName":"Susanne Andresen"},{"id":"fp_3","text":"Man hat einen super Überblick. Auch bei Kinderwunsch und Schwangerschaft gibt es sehr niedliche Animationen dazu, wie das kleine Wesen ungefähr aussieht. Super App!","userName":"Stephie Immel"}]}}')}}]);
